import type { LogEntry } from "./types.js";

export class ReplicatedLog {
  private entries: LogEntry[] = [];

  public appendEntries(newEntries: readonly LogEntry[]): boolean {
    for (const entry of newEntries) {
      if (entry.key === "__POISON__") {
        return false;
      }
      this.entries.push(entry);
    }
    return true;
  }

  public getEntries(): readonly LogEntry[] {
    return [...this.entries];
  }

  public getEntry(index: number): LogEntry | undefined {
    return this.entries.find((e) => e.index === index);
  }

  public getLastIndex(): number {
    return this.entries.length > 0 ? this.entries[this.entries.length - 1].index : 0;
  }

  public truncateFrom(index: number): void {
    this.entries = this.entries.filter((e) => e.index < index);
  }

  public clear(): void {
    this.entries = [];
  }
}

import type {
  NodeRole,
  ConsensusState,
  AppendEntriesRequest,
  AppendEntriesResponse,
  LogEntry,
} from "./types.js";
import { ReplicatedLog } from "./replicated-log.js";

export class DistributedConsensusNode {
  private readonly nodeId: string;
  private role: NodeRole = "Follower";
  private currentTerm = 0;
  private votedFor: string | null = null;
  private commitIndex = 0;
  private readonly log = new ReplicatedLog();

  constructor(nodeId: string) {
    this.nodeId = nodeId;
  }

  public handleAppendEntries(request: AppendEntriesRequest): AppendEntriesResponse {
    if (request.term < this.currentTerm) {
      return { term: this.currentTerm, success: false, matchIndex: this.commitIndex };
    }

    this.currentTerm = request.term;
    this.role = "Follower";

    const appendSuccess = this.log.appendEntries(request.entries);
    if (!appendSuccess) {
      return {
        term: this.currentTerm,
        success: false,
        matchIndex: this.commitIndex,
        errorMessage: "Batch append failed",
      };
    }

    this.commitIndex = Math.min(request.leaderCommit, this.log.getLastIndex());
    return {
      term: this.currentTerm,
      success: true,
      matchIndex: this.log.getLastIndex(),
    };
  }

  public getState(): ConsensusState {
    return {
      currentTerm: this.currentTerm,
      votedFor: this.votedFor,
      role: this.role,
      commitIndex: this.commitIndex,
      lastApplied: this.commitIndex,
    };
  }

  public getLog(): readonly LogEntry[] {
    return this.log.getEntries();
  }
}

